def route_contract_violations(root: Path) -> list[str]:
    constants: dict[str, object] = {}
    for node in ast.parse((root / ROUTES_PATH).read_text(encoding="utf-8")).body:
        if isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name) and node.value:
            if node.target.id in {"READ15_TEMPLATE", "SEARCH_TEMPLATE", "_RESOURCE_PREFIX", "ROUTE_SPECS"}:
                constants[node.target.id] = _literal(node.value, constants)
    from backend.adapters.inbound.api.routes import ROUTE_SPECS
    contract = json.loads((root / _CONTRACT).read_text(encoding="utf-8"))
    documented = tuple(
        (tuple(row["methods"]), row["path"], row["asset"]) for row in contract["routes"]
    )
    violations = []
    if constants.get("ROUTE_SPECS") != _EXPECTED_ROUTES:
        violations.append("AST_REGISTRY_DRIFT")
    if ROUTE_SPECS != _EXPECTED_ROUTES or documented != _EXPECTED_ROUTES:
        violations.append("CONTRACT_REGISTRY_DRIFT")
    for path in (root / "backend/adapters/inbound/api").rglob("*.py"):
        if path.relative_to(root).as_posix() != ROUTES_PATH:
            if "/api/v2" in path.read_text(encoding="utf-8"):
                violations.append("ROUTE_DECLARED_OUTSIDE_REGISTRY")
    return violations

def inventory_violations(root: Path, changed: set[str] | None = None) -> list[str]:
    contract = json.loads((root / _CONTRACT).read_text(encoding="utf-8"))
    assert contract["baseline_commit"] == _SEARCH_BASELINE
    assert contract["approved_inventory"] == list(EXPECTED_SEARCH_INVENTORY)
    if changed is None:
        changed = set()
        for arguments in (
            ["diff", "--name-only", _SEARCH_BASELINE, "--"],
            ["ls-files", "--others", "--exclude-standard"],
        ):
            result = subprocess.run(
                ["git", *arguments], cwd=root, capture_output=True, text=True, check=True
            )
            changed.update(result.stdout.splitlines())
    protected = {item["path"]: item["sha256"] for item in contract["protected_documents"]}
    assert protected == dict(EXPECTED_PROTECTED_DOCUMENTS)
    allowed = set(EXPECTED_SEARCH_INVENTORY)
    violations = sorted(changed - allowed - set(protected))
    for name, digest in protected.items():
        path = root / name
        if not path.is_file() or hashlib.sha256(path.read_bytes()).hexdigest() != digest:
            violations.append("PROTECTED_DOCUMENT_CHANGED:" + name)
    return violations

def test_existing_pure_contracts_and_original_guards_other_tests_preserved() -> None:
    expected = {
        "backend/adapters/inbound/api/local_browser.py":
            "cc7ee88ebbb41d17feb301c9707d1ab05efe3d1fa3118be8612c1b4c735d1148",
        "backend/infrastructure/config/schemas/http.py":
            "511336250f3a3274fe4f2f17f328771111250b0ec916a4e18723abc6b4ecf298",
    }
    for path, digest in expected.items():
        assert hashlib.sha256((ROOT / path).read_bytes()).hexdigest() == digest
    permitted = {
        "tests/architecture/test_local_browser_http_boundary_fitness.py": {
            "test_b04_adds_no_http_server_framework_or_route",
            "test_b04_adds_no_frontend_public_url_or_drive_runtime_dependency",
        },
        "tests/architecture/test_minimal_local_observability_fitness.py": {
            "test_http_observability_adds_no_server_framework_or_route",
        },
        "tests/architecture/test_security_recovery_observability_e2e_fitness.py": {
            "test_later_provider_work_preserves_phase_f_backend_owners",
        },
        "tests/architecture/test_resource_ref_contract_fitness.py": {
            "test_read15_keeps_one_field_and_deprecations_without_http_implementation",
        },
    }
    for path, changed_tests in permitted.items():
        old = subprocess.run(["git", "show", f"{BASELINE}:{path}"], cwd=ROOT,
                             capture_output=True, text=True, check=True).stdout
        old_functions = {
            node.name: ast.dump(node, include_attributes=False)
            for node in ast.parse(old).body if isinstance(node, ast.FunctionDef)
            and node.name not in changed_tests
        }
        current = {
            node.name: ast.dump(node, include_attributes=False)
            for node in ast.parse((ROOT / path).read_text(encoding="utf-8")).body
            if isinstance(node, ast.FunctionDef) and node.name not in changed_tests
        }
        assert current == old_functions

def test_only_approved_guard_functions_change_and_old_assertions_remain() -> None:
    scopes = {
        "tests/architecture/test_local_browser_product_boundary.py":
            {"route_contract_violations", "inventory_violations"},
        "tests/architecture/test_resource_ref_contract_fitness.py":
            {"test_read15_keeps_one_field_and_deprecations_without_http_implementation"},
        "tests/architecture/test_security_recovery_observability_e2e_fitness.py":
            {"test_later_provider_work_preserves_phase_f_backend_owners"},
        "tests/unit/test_local_browser_product_routes.py":
            {"test_registry_has_one_business_operation_and_three_assets"},
    }
    for path, allowed in scopes.items():
        old = functions(baseline_source(path))
        current = functions((ROOT / path).read_text("utf-8"))
        assert old.keys() == current.keys()
        assert {k: v for k, v in old.items() if k not in allowed} == {
            k: v for k, v in current.items() if k not in allowed
        }
    ref_path = "tests/architecture/test_resource_ref_contract_fitness.py"
    name = "test_read15_keeps_one_field_and_deprecations_without_http_implementation"
    old = next(n for n in ast.parse(baseline_source(ref_path)).body
               if isinstance(n, ast.FunctionDef) and n.name == name)
    current = next(n for n in ast.parse((ROOT / ref_path).read_text("utf-8")).body
                   if isinstance(n, ast.FunctionDef) and n.name == name)
    assert [ast.dump(n) for n in old.body[:-1]] == [ast.dump(n) for n in current.body[:-1]]
    unit_path = "tests/unit/test_local_browser_product_routes.py"
    name = "test_registry_has_one_business_operation_and_three_assets"
    old = next(n for n in ast.parse(baseline_source(unit_path)).body
               if isinstance(n, ast.FunctionDef) and n.name == name)
    current = next(n for n in ast.parse((ROOT / unit_path).read_text("utf-8")).body
                   if isinstance(n, ast.FunctionDef) and n.name == name)
    assert [ast.dump(n) for n in old.body[1:]] == [ast.dump(n) for n in current.body[1:]]

def test_reused_components_and_history_are_byte_identical() -> None:
    prep = ROOT / "docs/development/phase_12_18_h2_recherche_locale_preparation"
    inventory = json.loads((prep / "03_INVENTAIRE_FICHIERS_ET_GUARDS.json").read_text("utf-8"))
    for item in inventory["read_only_dependencies"]:
        assert hashlib.sha256((ROOT / item["path"]).read_bytes()).hexdigest() == item["sha256"]
    for name, digest in EXPECTED_PROTECTED_DOCUMENTS:
        assert hashlib.sha256((ROOT / name).read_bytes()).hexdigest() == digest
    # The old manifest is a historical working-tree snapshot. Check baseline Git blobs,
    # accepting only the Git EOL representation documented at entry.
    manifest_dir = ROOT / "docs/development/phase_12_18_h2_local_read15"
    for line in (manifest_dir / "MANIFEST_SHA256.txt").read_text("utf-8").splitlines():
        digest, name = line.split("  ", 1)
        relative = (manifest_dir / name).resolve().relative_to(ROOT).as_posix()
        raw = subprocess.run(
            ["git", "show", f"{_SEARCH_BASELINE}:{relative}"], cwd=ROOT,
            check=True, capture_output=True,
        ).stdout
        assert digest in {
            hashlib.sha256(raw).hexdigest(),
            hashlib.sha256(raw.replace(b"\r\n", b"\n").replace(b"\n", b"\r\n")).hexdigest(),
        }


